// OLED radar: servo HC-SR04'ü sağa sola çevirir; ekranda radar yelpazesi ve cisimler çizilir.
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <ESP32Servo.h>

const int SERVO_PIN = 13;
const int TRIG_PIN = 26;
const int ECHO_PIN = 27;        // HC-SR04 ECHO, gerilim bölücüden (5 V -> 3,3 V) gelir
const int SDA_PIN = 21;
const int SCL_PIN = 22;
const int ACI_BAS = 15;         // taramanın başladığı açı
const int ACI_SON = 165;        // taramanın bittiği açı
const int ADIM = 3;             // her adımda kaç derece dönsün
const int BEKLEME_MS = 30;      // servo yeni açıya otursun diye bekleme
const int MENZIL_CM = 100;      // ekranın dış halkası bu mesafe; ötesi gösterilmez

Adafruit_SSD1306 ekran(128, 64, &Wire, -1);
Servo servo;
const int MERKEZ_X = 64;        // radarın merkezi: ekranın alt ortası
const int MERKEZ_Y = 63;
const int YARICAP = 54;         // üstte yazıya 9 piksel kalır
int mesafeler[181];             // her açının son ölçümü (cm); -1 = cisim yok
int aci = ACI_BAS;
int yon = 1;
int enYakinCm = -1;
int enYakinAci = 0;

// Mesafeyi cm olarak döndürür; yankı yoksa -1.
int mesafeOlc() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  unsigned long sure = pulseIn(ECHO_PIN, HIGH, 30000);
  if (sure == 0) return -1;
  return (int)(sure / 58);
}

// Açı (derece) ve yarıçaptan ekran noktası. 0 derece sağda, 180 derece solda.
void noktaBul(int a, int r, int* x, int* y) {
  float rad = a * DEG_TO_RAD;
  *x = MERKEZ_X + (int)lround(r * cos(rad));
  *y = MERKEZ_Y - (int)lround(r * sin(rad));
}

void ciz(int cm) {
  int x, y, x2, y2;
  ekran.clearDisplay();
  // Mesafe halkaları: menzilin üçte biri, üçte ikisi ve tamamı.
  for (int i = 1; i <= 3; i++) ekran.drawCircle(MERKEZ_X, MERKEZ_Y, YARICAP * i / 3, SSD1306_WHITE);
  ekran.drawFastHLine(0, MERKEZ_Y, 128, SSD1306_WHITE);

  // Cisimler: noktayı çiz, arkasını dış halkaya kadar çizgiyle doldur.
  for (int a = ACI_BAS; a <= ACI_SON; a += ADIM) {
    int m = mesafeler[a];
    if (m <= 0 || m > MENZIL_CM) continue;
    noktaBul(a, m * YARICAP / MENZIL_CM, &x, &y);
    noktaBul(a, YARICAP, &x2, &y2);
    ekran.drawLine(x, y, x2, y2, SSD1306_WHITE);
    ekran.fillCircle(x, y, 1, SSD1306_WHITE);
  }

  // Tarama çizgisi.
  noktaBul(aci, YARICAP, &x, &y);
  ekran.drawLine(MERKEZ_X, MERKEZ_Y, x, y, SSD1306_WHITE);

  // Üst satır: açı solda, mesafe sağda. OLED'de derece işareti yok; "dr" yazılır.
  ekran.setTextSize(1);
  ekran.setCursor(0, 0);
  ekran.printf("%3d dr", aci);
  ekran.setCursor(80, 0);
  if (cm > 0 && cm <= MENZIL_CM) ekran.printf("%3d cm", cm);
  else ekran.print(" -- cm");
  ekran.display();
}

void setup() {
  Serial.begin(115200);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  for (int i = 0; i <= 180; i++) mesafeler[i] = -1;

  Wire.begin(SDA_PIN, SCL_PIN);
  if (!ekran.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED bulunamadi. Kablolari ve 0x3C adresini kontrol et.");
    while (true) delay(1000);
  }
  ekran.setTextColor(SSD1306_WHITE);

  servo.setPeriodHertz(50);
  servo.attach(SERVO_PIN, 500, 2400);
  servo.write(aci);
  delay(500);
  Serial.println("Radar basladi.");
}

void loop() {
  servo.write(aci);
  delay(BEKLEME_MS);
  int cm = mesafeOlc();
  mesafeler[aci] = cm;
  if (cm > 0 && cm <= MENZIL_CM && (enYakinCm < 0 || cm < enYakinCm)) {
    enYakinCm = cm;
    enYakinAci = aci;
  }
  ciz(cm);

  // Sonraki açı. Uca gelince yön değişir ve tarama özeti yazılır.
  aci += yon * ADIM;
  if (aci > ACI_SON || aci < ACI_BAS) {
    yon = -yon;
    aci += 2 * yon * ADIM;
    if (enYakinCm > 0) Serial.printf("Tarama bitti. En yakin cisim: %d cm, %d derece\n", enYakinCm, enYakinAci);
    else Serial.println("Tarama bitti. Menzilde cisim yok.");
    enYakinCm = -1;
  }
}
